import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

import { tv, type VariantProps } from "tailwind-variants";

export const buttonStyles = tv({
  base: "inline-flex shrink-0 cursor-default items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium tracking-[-0.01em] data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[disabled]:shadow-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-3 data-[focus-visible]:outline-ring",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 data-[pressed]:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 data-[pressed]:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted data-[pressed]:bg-muted",
      ghost: "text-foreground hover:bg-muted data-[pressed]:bg-muted",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 data-[pressed]:bg-destructive/90",
      nav: "text-foreground hover:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
    },
    size: {
      default: "h-11 px-5 text-sm",
      sm: "h-9 px-3.5 text-sm",
      lg: "h-12 px-6 text-sm",
      icon: "size-11 cursor-pointer p-0",
      nav: "h-9 w-full justify-center px-0 text-xs sm:justify-start sm:px-2.5",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonStyles,
} from "./button-styles";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  static?: boolean;
}

const MotionButton = motion.create(AriaButton);

export function Button({
  className,
  variant = "default",
  size = "default",
  static: isStatic = false,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      whileTap={isStatic || reduceMotion ? undefined : { scale: 0.96 }}
      transition={{ type: "spring", duration: 0.3, bounce: 0 }}
      className={composeRenderProps(className, (className) =>
        buttonStyles({ variant, size, className }),
      )}
      {...props}
    />
  );
}

"use client";

import {
  animate,
  type HTMLMotionProps,
  motion,
  useDragControls,
  useMotionValue,
  useReducedMotion,
  useTransform,
} from "motion/react";
import {
  createContext,
  type HTMLAttributes,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  Button as AriaButton,
  Dialog as AriaDialog,
  DialogTrigger as AriaDialogTrigger,
  type ButtonProps,
  composeRenderProps,
  type DialogProps,
  type DialogTriggerProps,
  Heading,
  type HeadingProps,
  Modal,
  ModalOverlay,
  type ModalOverlayProps,
  Text,
  type TextProps,
} from "react-aria-components";
import { X } from "reicon-react";
import { tv } from "tailwind-variants";
import { cn } from "./utils";
import { Button, type ButtonProps as StyledButtonProps } from "./button";

type Placement = "bottom" | "top" | "left" | "right";

const drawerSurfaceStyles = tv({
  base: "absolute flex flex-col overflow-hidden bg-card text-card-foreground shadow-[var(--shadow-float)] outline-none ring-1 ring-border/70",
  variants: {
    placement: {
      bottom: "inset-x-0 mx-auto w-full max-w-2xl bottom-0 rounded-t-xl",
      top: "inset-x-0 mx-auto w-full max-w-2xl top-0 rounded-b-xl",
      left: "inset-y-0 w-[min(26rem,100vw)] left-0 rounded-r-xl",
      right: "inset-y-0 w-[min(26rem,100vw)] right-0 rounded-l-xl",
    },
  },
  defaultVariants: { placement: "bottom" },
});

interface DrawerState {
  open: boolean;
  present: boolean;
  close: () => void;
  exitComplete: () => void;
}

const DrawerContext = createContext<DrawerState | null>(null);
const DrawerContentContext = createContext<{
  placement: Placement;
  point: number;
  startDrag: (event: React.PointerEvent<HTMLButtonElement>) => void;
  onHandleKeyDown: (event: React.KeyboardEvent<HTMLButtonElement>) => void;
  onHandlePress: () => void;
} | null>(null);

function useDrawer() {
  const context = useContext(DrawerContext);
  if (!context) throw new Error("Drawer parts must be inside <Drawer>.");
  return context;
}

export function Drawer({
  defaultOpen,
  isOpen,
  onOpenChange,
  ...props
}: DialogTriggerProps) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen ?? false);
  const open = isOpen ?? internalOpen;
  const [present, setPresent] = useState(open);

  useEffect(() => {
    if (open) setPresent(true);
  }, [open]);

  const changeOpen = (next: boolean) => {
    if (isOpen === undefined) setInternalOpen(next);
    if (next) setPresent(true);
    onOpenChange?.(next);
  };
  const exitComplete = useCallback(() => {
    if (!open) setPresent(false);
  }, [open]);

  return (
    <DrawerContext.Provider
      value={{
        open,
        present,
        close: () => changeOpen(false),
        exitComplete,
      }}
    >
      <AriaDialogTrigger {...props} isOpen={open} onOpenChange={changeOpen} />
    </DrawerContext.Provider>
  );
}

export function DrawerTrigger(props: StyledButtonProps) {
  return <Button {...props} data-slot="drawer-trigger" />;
}

export interface DrawerContentProps
  extends Omit<DialogProps, "children" | "className"> {
  ref?: React.Ref<HTMLElement>;
  children: ReactNode;
  /** Classes for the drawer surface. */
  className?: React.ComponentProps<typeof Modal>["className"];
  placement?: Placement;
  /** Bottom drawers only. Fractions of the visible viewport, between 0 and 1. */
  snapPoints?: number[];
  defaultSnapPoint?: number;
  snapPoint?: number;
  onSnapPointChange?: (point: number) => void;
  overlayProps?: Omit<
    ModalOverlayProps,
    "children" | "isOpen" | "onOpenChange" | "isExiting" | "render"
  >;
}

const DEFAULT_SNAPS = [0.85];
const spring = { type: "spring" as const, stiffness: 380, damping: 38 };

export function DrawerContent({
  children,
  className,
  placement = "bottom",
  snapPoints = DEFAULT_SNAPS,
  defaultSnapPoint,
  snapPoint,
  onSnapPointChange,
  overlayProps,
  ...props
}: DrawerContentProps) {
  const { open, present, close, exitComplete } = useDrawer();
  const reduceMotion = useReducedMotion();
  const dragControls = useDragControls();
  const wasOpen = useRef(false);
  const dragged = useRef(false);
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const [viewport, setViewport] = useState({ height: 0, width: 0 });
  const points = useMemo(() => {
    const valid = snapPoints.filter(
      (point) => Number.isFinite(point) && point > 0 && point <= 1,
    );
    return valid.length
      ? [...new Set(valid)].sort((a, b) => a - b)
      : DEFAULT_SNAPS;
  }, [snapPoints]);
  const [internalPoint, setInternalPoint] = useState(
    defaultSnapPoint ?? points[0],
  );
  const requestedPoint = snapPoint ?? internalPoint;
  const point = points.reduce((nearest, candidate) =>
    Math.abs(candidate - requestedPoint) < Math.abs(nearest - requestedPoint)
      ? candidate
      : nearest,
  );
  const maxHeight = points[points.length - 1] * viewport.height;
  const sideWidth = Math.min(416, viewport.width);
  const topHeight = Math.min(416, viewport.height);
  const vertical = placement === "bottom" || placement === "top";
  const offset = (points[points.length - 1] - point) * viewport.height;
  const closedSide = (placement === "left" ? -1 : 1) * sideWidth;
  const progress = useTransform(vertical ? y : x, (value) =>
    Math.max(
      0,
      1 -
        Math.min(
          1,
          Math.abs(value) /
            (placement === "bottom"
              ? maxHeight || 1
              : placement === "top"
                ? topHeight || 1
                : sideWidth || 1),
        ),
    ),
  );

  useLayoutEffect(() => {
    const update = () =>
      setViewport({
        height: window.visualViewport?.height ?? window.innerHeight,
        width: window.innerWidth,
      });
    update();
    window.addEventListener("resize", update);
    window.visualViewport?.addEventListener("resize", update);
    return () => {
      window.removeEventListener("resize", update);
      window.visualViewport?.removeEventListener("resize", update);
    };
  }, []);

  useLayoutEffect(() => {
    if (!viewport.height || (!open && !present)) return;
    const value = vertical ? y : x;
    const closed =
      placement === "bottom"
        ? maxHeight
        : placement === "top"
          ? -topHeight
          : closedSide;
    const target = open ? (placement === "bottom" ? offset : 0) : closed;
    if (open && !wasOpen.current) value.set(closed);
    wasOpen.current = open;
    const controls = animate(
      value,
      target,
      reduceMotion
        ? { duration: 0 }
        : open
          ? spring
          : { duration: 0.24, ease: "easeOut" },
    );
    let cancelled = false;
    if (!open)
      void controls.then(() => {
        if (!cancelled) exitComplete();
      });
    return () => {
      cancelled = true;
      controls.stop();
    };
  }, [
    open,
    present,
    placement,
    viewport.height,
    offset,
    maxHeight,
    closedSide,
    topHeight,
    vertical,
    reduceMotion,
    x,
    y,
    exitComplete,
  ]);

  const selectPoint = (next: number) => {
    if (snapPoint === undefined) setInternalPoint(next);
    onSnapPointChange?.(next);
    animate(
      y,
      (points[points.length - 1] - next) * viewport.height,
      reduceMotion ? { duration: 0 } : spring,
    );
  };

  const onHandleKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    if (event.key === "Enter" || event.key === " ") dragged.current = false;
    if (placement !== "bottom") return;
    const index = points.indexOf(point);
    if (event.key === "ArrowUp" || event.key === "Home") {
      event.preventDefault();
      selectPoint(
        points[
          event.key === "Home"
            ? points.length - 1
            : Math.min(points.length - 1, index + 1)
        ],
      );
    } else if (event.key === "ArrowDown" || event.key === "End") {
      event.preventDefault();
      if (event.key === "End" || index === 0) close();
      else selectPoint(points[index - 1]);
    }
  };

  const onDragEnd: HTMLMotionProps<"div">["onDragEnd"] = (_, info) => {
    if (placement === "bottom") {
      const stops = points.map((snap) => ({
        snap,
        position: (points[points.length - 1] - snap) * viewport.height,
      }));
      const projected = y.get() + info.velocity.y * 0.18;
      const nearest = [...stops, { snap: 0, position: maxHeight }].reduce(
        (a, b) =>
          Math.abs(a.position - projected) < Math.abs(b.position - projected)
            ? a
            : b,
      );
      if (Math.abs(info.velocity.y) > 650) {
        const ordered = [...stops, { snap: 0, position: maxHeight }].sort(
          (a, b) => a.position - b.position,
        );
        const next =
          info.velocity.y > 0
            ? ordered.find((stop) => stop.position > offset + 1)
            : [...ordered].reverse().find((stop) => stop.position < offset - 1);
        if (next) {
          if (next.snap === 0) close();
          else selectPoint(next.snap);
          return;
        }
      }
      if (nearest.snap === 0) close();
      else selectPoint(nearest.snap);
    } else {
      const value = placement === "top" ? y : x;
      const velocity = placement === "top" ? info.velocity.y : info.velocity.x;
      const edge = placement === "top" ? -topHeight : closedSide;
      const projected = value.get() + velocity * 0.18;
      if (
        projected * Math.sign(edge) > Math.abs(edge) * 0.35 ||
        velocity * Math.sign(edge) > 650
      )
        close();
      else animate(value, 0, reduceMotion ? { duration: 0 } : spring);
    }
  };

  return (
    <ModalOverlay
      {...overlayProps}
      data-slot="drawer-overlay"
      isDismissable={overlayProps?.isDismissable ?? true}
      isExiting={!open && present}
      className={composeRenderProps(overlayProps?.className, (className) =>
        cn("fixed inset-0 z-50 overflow-hidden", className),
      )}
    >
      <motion.div
        aria-hidden="true"
        data-slot="drawer-backdrop"
        className="pointer-events-none absolute inset-0 bg-foreground/40 backdrop-blur-sm dark:bg-foreground/20"
        style={{ opacity: progress }}
      />
      <Modal
        data-slot="drawer-modal"
        render={(domProps) => (
          <motion.div
            {...(domProps as HTMLMotionProps<"div">)}
            onKeyDownCapture={(event) => {
              if (
                event.key === "Escape" &&
                !overlayProps?.isKeyboardDismissDisabled &&
                event.currentTarget.contains(event.target as Node)
              ) {
                // Some child controls stop propagation without handling Escape.
                // Give them a chance to consume it before closing the drawer.
                queueMicrotask(() => {
                  if (!event.defaultPrevented) close();
                });
              }
            }}
            style={{
              ...domProps.style,
              x,
              y,
              height:
                placement === "bottom"
                  ? maxHeight
                    ? `${maxHeight}px`
                    : `${points[points.length - 1] * 100}dvh`
                  : placement === "top"
                    ? `${topHeight || 416}px`
                    : undefined,
            }}
            drag={vertical ? "y" : "x"}
            dragControls={dragControls}
            dragListener={false}
            dragMomentum={false}
            dragElastic={0}
            onDragStart={() => {
              dragged.current = true;
            }}
            dragConstraints={
              placement === "bottom"
                ? { top: 0, bottom: maxHeight }
                : placement === "top"
                  ? { top: -topHeight, bottom: 0 }
                  : {
                      left: placement === "left" ? -sideWidth : 0,
                      right: placement === "right" ? sideWidth : 0,
                    }
            }
            onDragEnd={onDragEnd}
          />
        )}
        className={composeRenderProps(className, (className) =>
          drawerSurfaceStyles({ placement, className }),
        )}
      >
        <AriaDialog
          {...props}
          data-slot="drawer-content"
          className="flex min-h-0 flex-1 flex-col outline-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-ring"
        >
          <DrawerContentContext.Provider
            value={{
              placement,
              point,
              startDrag: (event) => {
                dragged.current = false;
                dragControls.start(event);
              },
              onHandleKeyDown,
              onHandlePress: () => {
                if (dragged.current) return;
                if (placement !== "bottom") close();
                else if (points.length > 1)
                  selectPoint(
                    point === points[points.length - 1]
                      ? points[0]
                      : points[points.indexOf(point) + 1],
                  );
                else close();
              },
            }}
          >
            {children}
            {placement === "bottom" && (
              <output className="sr-only">
                Drawer height {Math.round(point * 100)} percent
              </output>
            )}
          </DrawerContentContext.Provider>
        </AriaDialog>
      </Modal>
    </ModalOverlay>
  );
}

export function DrawerHandle({ className, ...props }: ButtonProps) {
  const context = useContext(DrawerContentContext);
  if (!context) throw new Error("DrawerHandle must be inside <DrawerContent>.");
  return (
    <AriaButton
      {...props}
      data-slot="drawer-handle"
      aria-label={
        props["aria-label"] ??
        (context.placement === "bottom"
          ? `Resize drawer, ${Math.round(context.point * 100)} percent visible. Use arrow keys, Home, or End.`
          : "Dismiss drawer or drag to close")
      }
      onPointerDown={(event) => {
        props.onPointerDown?.(event);
        if (!event.isDefaultPrevented()) context.startDrag(event);
      }}
      onKeyDown={(event) => {
        props.onKeyDown?.(event);
        if (!event.isDefaultPrevented()) context.onHandleKeyDown(event);
      }}
      onPress={(event) => {
        props.onPress?.(event);
        context.onHandlePress();
      }}
      className={composeRenderProps(className, (className) =>
        cn(
          "mx-auto flex min-h-11 min-w-16 shrink-0 cursor-grab items-center justify-center touch-none active:cursor-grabbing data-[focus-visible]:outline-2 data-[focus-visible]:outline-ring",
          className,
        ),
      )}
    >
      {props.children ?? (
        <span
          aria-hidden="true"
          data-slot="drawer-handle-grip"
          className="h-1 w-9 rounded-full bg-muted-foreground/50"
        />
      )}
    </AriaButton>
  );
}

export function DrawerHeader({
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="drawer-header"
      className={cn("shrink-0 px-6 pt-4", className)}
    />
  );
}

export function DrawerTitle({ className, ...props }: HeadingProps) {
  return (
    <Heading
      {...props}
      slot="title"
      data-slot="drawer-title"
      className={cn("text-xl font-semibold tracking-[-0.04em]", className)}
    />
  );
}

export function DrawerDescription({ className, ...props }: TextProps) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="drawer-description"
      className={cn(
        "mt-2 block text-sm leading-6 text-muted-foreground",
        className,
      )}
    />
  );
}

export function DrawerBody({
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="drawer-body"
      className={cn(
        "min-h-0 flex-1 overflow-y-auto overscroll-contain px-6 py-5",
        className,
      )}
    />
  );
}

export function DrawerFooter({
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="drawer-footer"
      className={cn(
        "flex shrink-0 justify-end gap-2 border-t border-border px-6 py-4 pb-[max(1rem,env(safe-area-inset-bottom))]",
        className,
      )}
    />
  );
}

export function DrawerClose({
  children,
  onPress,
  variant = "ghost",
  size,
  ...props
}: StyledButtonProps) {
  const { close } = useDrawer();
  return (
    <Button
      {...props}
      data-slot="drawer-close"
      variant={variant}
      size={size ?? (children ? "default" : "icon")}
      onPress={(event) => {
        onPress?.(event);
        close();
      }}
      aria-label={
        props["aria-label"] ?? (children ? undefined : "Close drawer")
      }
    >
      {children ?? <X size={17} aria-hidden="true" />}
    </Button>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { createContext, useContext, useState } from "react";
import {
  Checkbox as AriaCheckbox,
  type CheckboxProps as AriaCheckboxProps,
  composeRenderProps,
} from "react-aria-components";
import { Check, Minus } from "reicon-react";
import { cn } from "./utils";

const CheckboxStateContext = createContext({
  isSelected: false,
  isIndeterminate: false,
});

export interface CheckboxProps
  extends Omit<AriaCheckboxProps, "className" | "children"> {
  ref?: React.Ref<HTMLLabelElement>;
  className?: AriaCheckboxProps["className"];
  description?: string;
  children?: AriaCheckboxProps["children"];
  checked?: boolean | "indeterminate";
  defaultChecked?: boolean | "indeterminate";
  onCheckedChange?: (checked: boolean) => void;
}

export function Checkbox({
  children,
  description,
  className,
  checked,
  defaultChecked,
  onCheckedChange,
  ...props
}: CheckboxProps) {
  const [initialIndeterminate, setInitialIndeterminate] = useState(
    defaultChecked === "indeterminate",
  );
  return (
    <AriaCheckbox
      {...props}
      isSelected={checked === undefined ? props.isSelected : checked === true}
      defaultSelected={
        defaultChecked === undefined
          ? props.defaultSelected
          : defaultChecked === true
      }
      isIndeterminate={
        checked === undefined
          ? initialIndeterminate || props.isIndeterminate
          : checked === "indeterminate"
      }
      onChange={(value) => {
        setInitialIndeterminate(false);
        props.onChange?.(value);
        onCheckedChange?.(value);
      }}
      data-slot="checkbox"
      className={composeRenderProps(className, (className) =>
        cn(
          "group inline-flex min-h-11 cursor-pointer items-start gap-3 rounded-md text-sm text-foreground data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring",
          typeof children === "string" && !description && "items-center",
          className,
        ),
      )}
    >
      {(state) => (
        <CheckboxStateContext.Provider value={state}>
          {typeof children === "function" ? (
            children(state)
          ) : typeof children === "string" || children == null ? (
            <>
              <CheckboxIndicator />
              {(children || description) && (
                <span className="pt-0.5">
                  {children && (
                    <span className="block font-medium">{children}</span>
                  )}
                  {description && (
                    <span className="mt-1 block text-xs leading-5 text-muted-foreground">
                      {description}
                    </span>
                  )}
                </span>
              )}
            </>
          ) : (
            children
          )}
        </CheckboxStateContext.Provider>
      )}
    </AriaCheckbox>
  );
}

export function CheckboxIndicator({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  const { isSelected, isIndeterminate } = useContext(CheckboxStateContext);
  const reduceMotion = useReducedMotion();
  const isChecked = isSelected || isIndeterminate;
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="checkbox-indicator"
      className={cn(
        "mt-0.5 grid size-5 shrink-0 place-items-center rounded-md border border-input bg-card shadow-[var(--shadow-inset)] group-hover:border-primary/60 group-data-[selected]:border-primary group-data-[selected]:bg-primary group-data-[indeterminate]:border-primary group-data-[indeterminate]:bg-primary",
        className,
      )}
    >
      <motion.span
        initial={false}
        animate={{
          scale: isChecked ? 1 : 0.25,
          opacity: isChecked ? 1 : 0,
          filter: isChecked ? "blur(0px)" : "blur(4px)",
        }}
        transition={
          reduceMotion
            ? { duration: 0 }
            : { type: "spring", duration: 0.3, bounce: 0 }
        }
        className="text-primary-foreground"
      >
        {isIndeterminate ? (
          <Minus size={13} strokeWidth={2.5} />
        ) : (
          <Check size={13} strokeWidth={2.5} />
        )}
      </motion.span>
    </span>
  );
}

export function CheckboxLabel({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="checkbox-label"
      className={cn("block font-medium", className)}
    />
  );
}

export function CheckboxDescription({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="checkbox-description"
      className={cn(
        "mt-1 block text-xs leading-5 text-muted-foreground",
        className,
      )}
